def score_typology(answers):
    # answers: list of (dichotomy, side) e.g. ('EI', 'I'), ('TF', 'T') ...
    # A miniature preference-clarity scorer: the instrument's core arithmetic.
    from collections import Counter
    tallies = {}
    for dichotomy, side in answers:
        tallies.setdefault(dichotomy, Counter())[side] += 1
    result = {}
    for d, counts in tallies.items():
        first, second = d[0], d[1]
        total = counts[first] + counts[second]
        winner = first if counts[first] >= counts[second] else second
        clarity = abs(counts[first] - counts[second]) / total * 100
        result[d] = (winner, round(clarity, 1))
    return result

sample = [('EI','I')]*7 + [('EI','E')]*3 + [('TF','T')]*6 + [('TF','F')]*4
print(score_typology(sample))  # -> {'EI': ('I', 40.0), 'TF': ('T', 20.0)}
